INSERT INTO `roles` (`id`, `name`, `is_system`, `slug`, `description`, `created_at`, `updated_at`) VALUES
(1, 'Super Admin', 1, 'super-admin', 'Full system access with ability to manage roles, permissions, and security settings', '2026-01-22 13:08:14', '2026-01-28 11:57:45'),
(2, 'Administrator', 0, 'administrator', 'General administrative access with limited system configuration capabilities', '2026-01-22 13:08:14', '2026-01-28 07:45:50'),
(3, 'Chief', 1, 'chief', 'Kitchen operations: recipes, inventory viewing, menu planning', '2026-01-22 13:08:14', '2026-01-28 11:57:45'),
(4, 'Service Manager', 1, 'service-manager', 'Customer-facing operations: orders, reservations, customer management', '2026-01-22 13:08:14', '2026-01-28 11:57:45'),
(5, 'Finance Manager', 0, 'finance-manager', 'Financial operations: payments, invoices, expenses, financial reports', '2026-01-22 13:08:14', '2026-01-22 13:08:14'),
(6, 'HR Manager', 0, 'hr-manager', 'Human resources: employee management, payroll, attendance, shifts', '2026-01-22 13:08:14', '2026-01-22 13:08:14'),
(7, 'Inventory Manager', 0, 'inventory-manager', 'Full inventory control: stock management, suppliers, purchase orders', '2026-01-22 13:08:14', '2026-01-22 13:08:14'),
(8, 'Operations Manager', 0, 'operations-manager', 'Operational setup: locations, tables, floors, operating hours', '2026-01-22 13:08:14', '2026-01-22 13:08:14'),
(9, 'Viewer', 0, 'viewer', 'Read-only access to reports, orders, and inventory for auditing purposes', '2026-01-22 13:08:14', '2026-01-22 13:08:14'),
